// import = bring in code from another file or package
// useEffect = run code AFTER the screen is drawn (timers, events, browser APIs); re-runs when its [deps] change
import { useEffect } from 'react';
// import = bring in code from another file or package
// RouterProvider = shows the page that matches the current URL
import { RouterProvider } from 'react-router';
// import = bring in code from another file or package
// useRestoreSessionMutation = generated by RTK Query: gives [trigger, { isLoading }]; calling trigger sends the change
import { useRestoreSessionMutation } from '@/features/auth/authApi';
// import = bring in code from another file or package
import { router } from '@/router';
// import = bring in code from another file or package
import { ServerErrorDialog } from '@/components/layout/ServerErrorDialog';

// On first load, try to restore the admin session from the refresh cookie.
// Until it answers, auth status is "loading" and pages show "Checking session...".
// export = other files can import this
// function Name() = a React component (capital letter): returns what to show (JSX)
export function App() {
  // const = a name for a value that is never reassigned
  // [a, b] = destructuring: take the first and second items of an array
  // useRestoreSessionMutation = generated by RTK Query: gives [trigger, { isLoading }]; calling trigger sends the change
  const [restoreSession] = useRestoreSessionMutation();
  // useEffect = run code AFTER the screen is drawn (timers, events, browser APIs); re-runs when its [deps] change
  // => = an arrow function (a short function)
  useEffect(() => {
    void restoreSession();
  }, [restoreSession]);
  // return = give this value back and stop the function here
  return (
    // <> </> = a fragment: groups elements without adding an extra HTML element
    <>
      {/* RouterProvider = shows the page that matches the current URL
         { } in JSX = run JavaScript here and show its result */}
      <RouterProvider router={router} />
      {/* "Something went wrong, retry" popup for server errors (5xx), on every page incl. login */}
      <ServerErrorDialog />
    </>
  );
}
